INSERT INTO `crafts` (`id`, `name`, `category`, `state`, `district`, `description`, `ai_description`, `lat`, `lng`, `image_url`, `created_at`) VALUES (101,'Pashmina Shawl','Textile','Jammu and Kashmir','Srinagar','Hand-spun fine wool shawl woven from Changthangi goat hair, prized for centuries for its warmth and softness.','Discover the timeless elegance of SrinagarΓÇÖs legendary Pashmina Shawl, a textile treasure prized for centuries for its unmatched warmth and softness. Hand-spun from the fine wool of the Changthangi goat, each piece represents the rich heritage of Jammu and Kashmir. Wrap yourself in this cozy masterpiece and experience a beautiful tradition you can take home with you.',34.083700,74.797300,'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1f/Mandala_Chandar%2C_Kashmir_1840.jpg/330px-Mandala_Chandar%2C_Kashmir_1840.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail','2026-08-17 12:55:19'),(102,'Kashmiri Papier-Mache','Handicraft','Jammu and Kashmir','Srinagar','Intricately hand-painted decorative objects made from paper pulp, a Persian-origin craft flourishing in Kashmir since the 14th century.','Discover the enchanting world of Kashmiri Papier-Mache, a beautiful craft of Persian origin that has flourished in Srinagar since the 14th century. You will be captivated by how simple paper pulp is transformed into intricately hand-painted decorative objects. Bring home one of these stunning creations as a beautiful keepsake of your journey through Kashmir.',34.083700,74.797300,'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d8/Pen_Box_%28qalamdan%29_LACMA_M.89.160a-b.jpg/330px-Pen_Box_%28qalamdan%29_LACMA_M.89.160a-b.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail','2026-08-17 12:55:19'),(103,'Chikankari Embroidery','Textile','Uttar Pradesh','Lucknow','Delicate white-thread hand embroidery on fine fabric, originating in Mughal-era Lucknow.','Discover the timeless elegance of Lucknow with Chikankari, a breathtaking textile art originating from the Mughal era. This exquisite craft features delicate white thread meticulously hand-embroidered onto fine fabric, creating a look of pure, lightweight beauty. It is a stunning piece of Uttar Pradesh\'s heritage that is sure to capture your heart.',26.846700,80.946200,'https://upload.wikimedia.org/wikipedia/commons/thumb/0/06/Craft_Artisans_of_India_02.jpg/330px-Craft_Artisans_of_India_02.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail','2026-08-17 12:55:19'),(104,'Banarasi Silk Saree','Textile','Uttar Pradesh','Varanasi','Opulent silk sarees woven with gold and silver brocade, a Varanasi weaving tradition over 500 years old.','Discover the breathtaking artistry of Varanasi, Uttar Pradesh, through the legendary Banarasi Silk Saree, a magnificent textile tradition dating back over 500 years. These opulent silk sarees are woven with gold and silver brocade, creating a true masterpiece of design. We invite you to explore this historic weaving tradition and experience the rich heritage of Varanasi.',25.317600,82.973900,'https://upload.wikimedia.org/wikipedia/commons/thumb/4/4e/%27Sari%27_from_Varanasi_%28north-central_India%29%2C_silk_and_gold-wrapped_silk_yarn_with_supplementary_weft_brocade.jpg/330px-%27Sari%27_from_Varanasi_%28north-central_India%29%2C_silk_and_gold-wrapped_silk_yarn_with_supplementary_weft_brocade.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail','2026-08-17 12:55:19'),(105,'Moradabad Brassware','Metalwork','Uttar Pradesh','Moradabad','Ornate hand-engraved brass utensils and decor, earning Moradabad the title \'Brass City of India\'.','Discover the shimmering artistry of Moradabad, famously known as the \'Brass City of India\' in Uttar Pradesh. Here, skilled hands transform metal into exquisite hand-engraved brass utensils and ornate home decor. Take home a piece of this beautiful traditional metalwork as a lasting memory of your journey.',28.838600,78.773300,'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a7/New_Moradabad_Skyline_NH_24.jpg/330px-New_Moradabad_Skyline_NH_24.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail','2026-08-17 12:55:19'),(106,'Madhubani Painting','Art','Bihar','Madhubani','Vivid folk paintings using natural dyes, traditionally created by women of the Mithila region on walls and now on paper/canvas.','Discover the vibrant world of Madhubani painting, a mesmerizing folk art originating from Bihar\'s Mithila region. Traditionally painted by local women on household walls using rich natural dyes, these vivid designs are now beautifully captured on paper and canvas. Immerse yourself in this stunning, living heritage that connects you directly to the artistic heart of the region.',26.357300,86.072500,'https://upload.wikimedia.org/wikipedia/commons/thumb/6/67/Madhubani_Mahavidyas.jpg/330px-Madhubani_Mahavidyas.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail','2026-08-17 12:55:19'),(107,'Kanchipuram Silk Saree','Textile','Tamil Nadu','Kanchipuram','Heavy silk sarees with wide contrast borders and temple-inspired motifs, woven by artisan families for generations.','Step into the rich heritage of Tamil Nadu with the exquisite Kanchipuram Silk Saree, lovingly woven by dedicated artisan families for generations. These luxurious, heavy silk sarees are instantly recognizable by their striking wide contrast borders and beautiful, temple-inspired motifs. Wrap yourself in a piece of living history and experience the timeless elegance of this legendary Indian textile.',12.834200,79.703600,'https://upload.wikimedia.org/wikipedia/commons/thumb/c/cd/Kanchipuram_sarees_%287642282772%29.jpg/330px-Kanchipuram_sarees_%287642282772%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail','2026-08-17 12:55:19'),(108,'Thanjavur Painting','Art','Tamil Nadu','Thanjavur','Classical South Indian painting style using gold foil, semi-precious stones, and rich colors, dating to the Maratha court era.','Step into a world of royal elegance with Thanjavur Painting, a classical South Indian art style originating from the Maratha court era of Tamil Nadu. These captivating masterpieces are brought to life with rich, vibrant colors and intricately adorned with shimmering gold foil and semi-precious stones. It is a dazzling heritage treasure that is sure to captivate you as you explore the region\'s artistic wonders.',10.787000,79.137800,'https://upload.wikimedia.org/wikipedia/commons/thumb/f/fb/Thanjavur_art_from_south_India.jpg/330px-Thanjavur_art_from_south_India.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail','2026-08-17 12:55:19'),(109,'Channapatna Toys','Handicraft','Karnataka','Ramanagara','Colorful lacquered wooden toys and dolls, a craft tradition dating back to Tipu Sultan\'s era.','Discover the cheerful world of Channapatna Toys, a cherished craft from Ramanagara, Karnataka, dating back to the era of Tipu Sultan. These delightfully vibrant, lacquered wooden toys and dolls are beautifully handcrafted, bringing a splash of color and living history into your hands. Take home a piece of this warm, timeless tradition to brighten your journey.',12.651900,77.200400,'https://upload.wikimedia.org/wikipedia/commons/thumb/b/ba/Wooden_toys.JPG/330px-Wooden_toys.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail','2026-08-17 12:55:19'),(110,'Bidriware','Metalwork','Karnataka','Bidar','Distinctive blackened metal handicraft inlaid with silver, originating in 14th-century Bidar under Bahmani rule.','Discover the striking beauty of Bidriware, a unique metalwork tradition that has flourished in Bidar, Karnataka since the 14th century under Bahmani rule. You will be captivated by the dramatic contrast of shimmering silver intricately inlaid into deeply blackened metal. It is a stunning piece of history to carry with you from your travels.',17.910400,77.519900,'https://upload.wikimedia.org/wikipedia/commons/thumb/1/12/Bidriware_Hookah.jpg/330px-Bidriware_Hookah.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail','2026-08-17 12:55:19'),(111,'Mysore Silk Saree','Textile','Karnataka','Mysuru','Pure silk sarees with a signature sheen, woven using silk from KSIC\'s own mills since the 1930s.','Wrap yourself in the breathtaking elegance of the Mysore Silk Saree, a timeless textile treasure from Mysuru, Karnataka. Renowned for its signature sheen, each pure silk masterpiece is woven using silk from KSIC\'s own mills, a proud tradition dating back to the 1930s. Discover this exquisite craft and take home a piece of the region\'s living heritage.',12.295800,76.639400,'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b2/Mysore_Silk_Saree.jpg/330px-Mysore_Silk_Saree.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail','2026-08-17 12:55:19'),(112,'Pochampally Ikat','Textile','Telangana','Yadadri Bhuvanagiri','Geometric tie-dye woven textiles, earning Pochampally village the nickname \'Silk City of India\'.','Step into the colorful world of Yadadri Bhuvanagiri, Telangana, and discover Pochampally Ikat, the stunning textile that earned Pochampally village the nickname \"Silk City of India.\" This captivating craft features mesmerizing geometric patterns brought to life through a meticulous tie-dye and weaving process. Take home a piece of this rich heritage and let its timeless beauty be a highlight of your journey.',17.349200,78.975600,'https://upload.wikimedia.org/wikipedia/commons/thumb/3/3d/Hermann_Linde_-_Girl_standing_in_a_veranda_wearing_a_Pochampalli_sari_%28ca.1895%29.jpg/330px-Hermann_Linde_-_Girl_standing_in_a_veranda_wearing_a_Pochampalli_sari_%28ca.1895%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail','2026-08-17 12:55:19'),(113,'Kondapalli Toys','Handicraft','Andhra Pradesh','Krishna','Lightweight wooden toys carved from local Tella Poniki wood, depicting rural life and mythology.','Discover the whimsical charm of Kondapalli Toys, a cherished traditional handicraft from the Krishna district of Andhra Pradesh. Lovingly carved from lightweight, local Tella Poniki wood, these delightful figures beautifully capture the essence of rural life and ancient mythology. Bring home one of these unique treasures to keep the spirit of your journey alive.',16.612000,80.572200,'https://upload.wikimedia.org/wikipedia/commons/thumb/9/93/Kondapalli_toys_at_a_house_in_Vijayawada.jpg/330px-Kondapalli_toys_at_a_house_in_Vijayawada.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail','2026-08-17 12:55:19'),(114,'Bastar Dhokra Art','Metalwork','Chhattisgarh','Bastar','Ancient lost-wax metal casting technique used by tribal artisans to create bronze figurines and decor.','Welcome to the world of Bastar Dhokra, an ancient metalwork art lovingly preserved by the tribal artisans of Chhattisgarh. Using a traditional lost-wax casting technique, these local creators handcraft beautiful bronze figurines and decor that reflect the spirit of their heritage. Bring home one of these unique bronze masterpieces to add a touch of timeless warmth to your space.',19.107300,81.954200,'https://upload.wikimedia.org/wikipedia/commons/thumb/3/35/Village_lady_grinding_ants_for_her_family.jpg/330px-Village_lady_grinding_ants_for_her_family.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail','2026-08-17 12:55:19'),(115,'Pattachitra Painting','Art','Odisha','Puri','Cloth-based scroll paintings with mythological themes, made using natural pigments by traditional Chitrakar artist families.','Step into the vibrant world of Pattachitra, a traditional cloth scroll painting art lovingly preserved by the Chitrakar artist families of Puri, Odisha. Crafted using rich natural pigments, each exquisite piece brings captivating mythological themes to life. It is a beautiful, living heritage that is sure to enchant you on your journey.',19.813500,85.831200,'https://upload.wikimedia.org/wikipedia/commons/thumb/7/7d/Odisha_Pattachitara_Depicting_Unconditional_Love_between_Radha_Krushna.jpg/330px-Odisha_Pattachitara_Depicting_Unconditional_Love_between_Radha_Krushna.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail','2026-08-17 12:55:19'),(116,'Sambalpuri Saree','Textile','Odisha','Sambalpur','Handwoven sarees using the distinctive Bandha (tie-dye) technique, featuring traditional Odia motifs like shankha and chakra.','Discover the rich textile heritage of Odisha through the breathtaking Sambalpuri Saree from Sambalpur. This handwoven masterpiece is created using the distinctive Bandha tie-dye technique, weaving traditional Odia motifs like the shankha and chakra into the fabric. Bring home a beautiful piece of local craftsmanship that is as rich in culture as it is in artistry.',21.466900,83.981200,'https://upload.wikimedia.org/wikipedia/commons/thumb/5/5b/Sambalpuri_saree1.jpg/330px-Sambalpuri_saree1.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail','2026-08-17 12:55:19'),(117,'Bankura Terracotta','Handicraft','West Bengal','Bankura','Iconic elongated-neck terracotta horses and folk art, hand-shaped by traditional Kumbhakar potter communities.','Welcome to the world of Bankura Terracotta, a captivating folk art from West Bengal. Hand-shaped by the traditional Kumbhakar potter community, these iconic, elongated-neck clay horses carry the warmth of local heritage. Bring home one of these unique treasures to keep a beautiful piece of BankuraΓÇÖs craftsmanship with you forever.',23.232400,87.073900,'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1e/Bishnupur_Terracotta_Horse_2.JPG/330px-Bishnupur_Terracotta_Horse_2.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail','2026-08-17 12:55:19'),(118,'Kutch Embroidery','Textile','Gujarat','Kutch','Vibrant mirror-work embroidery practiced by multiple pastoral communities of the Kutch desert region, each with a distinct style.','Discover the mesmerizing charm of Kutch Embroidery, a vibrant textile art from the desert region of Kutch, Gujarat. Famous for its dazzling mirror-work, this tradition is kept alive by multiple pastoral communities who each practice their own distinct, signature style. Let these radiant, reflective patterns guide you on an unforgettable journey through the region\'s rich cultural heritage.',23.733700,69.859700,'https://upload.wikimedia.org/wikipedia/commons/thumb/3/33/Prag_Mahal_Back_side_view%2C_Bhuj%2C_Gujarat%2C_India.jpg/330px-Prag_Mahal_Back_side_view%2C_Bhuj%2C_Gujarat%2C_India.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail','2026-08-17 12:55:19'),(119,'Patan Patola','Textile','Gujarat','Patan','Double ikat silk sarees so intricate that a single piece can take up to a year to weave, historically worn by royalty.','Step into the royal history of Patan, Gujarat, and discover Patan Patola, a breathtaking textile historically worn by royalty. These exquisite double ikat silk sarees are so incredibly intricate that a single piece can take up to a year to weave. We invite you to explore this legendary craft and marvel at the ultimate expression of dedication and skill.',23.849300,72.126600,'https://upload.wikimedia.org/wikipedia/commons/a/a5/Rani_ki_vav_02.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(120,'Blue Pottery','Handicraft','Rajasthan','Jaipur','Persian-influenced glazed pottery made without clay, using quartz powder, distinctive for its cobalt blue dye.','Discover the captivating charm of Jaipur\'s famous Blue Pottery, a unique handicraft defined by its brilliant cobalt blue dye. This beautiful Persian-influenced art is crafted entirely without clay, using a glazed quartz powder to create its signature look. It is the perfect, eye-catching keepsake to remember your travels through Rajasthan.',26.912400,75.787300,'https://upload.wikimedia.org/wikipedia/commons/a/af/Dr._Bhau_Daji_Lad_Museum_JEG1715.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(121,'Bagru Hand Block Print','Textile','Rajasthan','Jaipur','Natural dye hand-block textile printing tradition practiced by the Chhipa community in Bagru village for over 300 years.','Welcome to the beautiful world of Bagru, a village in Jaipur where the Chhipa community has kept a spectacular 300-year-old textile tradition alive. Here, fabrics are printed by hand using natural dyes in a hand-block process passed down through generations. Explore this timeless Rajasthani craft and take home a piece of living history.',26.899800,75.545700,'https://upload.wikimedia.org/wikipedia/commons/thumb/d/dc/Woman_doing_Block_Printing_at_Bagru_village%2C_Jaipur%2C_India.jpg/330px-Woman_doing_Block_Printing_at_Bagru_village%2C_Jaipur%2C_India.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail','2026-08-17 12:55:19'),(122,'Phulkari Embroidery','Textile','Punjab','Patiala','Vibrant floral thread-work embroidery on shawls and dupattas, traditionally made by women for weddings and festivals.','Discover the radiant charm of Phulkari, a traditional textile art from Patiala, Punjab, featuring vibrant floral thread-work. Traditionally embroidered by women for weddings and festive celebrations, these colorful shawls and dupattas are a beautiful expression of regional joy. Wrap yourself in this gorgeous handicraft and take a piece of Punjab\'s warm heritage home with you.',30.339800,76.386900,'https://upload.wikimedia.org/wikipedia/commons/thumb/7/71/Contemporary_Phulkari_design.jpg/330px-Contemporary_Phulkari_design.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail','2026-08-17 12:55:19'),(123,'Warli Painting','Art','Maharashtra','Palghar','Minimalist tribal wall art using geometric white shapes on mud backgrounds, practiced by the Warli tribe for centuries.','Discover the timeless beauty of Warli Painting, a centuries-old tribal wall art from Palghar, Maharashtra. Practiced by the Warli tribe, this captivating style uses minimalist white geometric shapes set against warm mud backgrounds to create elegant, striking designs. It is a beautiful, inviting window into a living heritage that will truly enrich your journey.',19.696700,72.765400,'https://upload.wikimedia.org/wikipedia/commons/thumb/9/94/Painted_prayers%2C_Warli_paintings%2C_at_Sanskriti_Kendra%2C_Anandagram%2C_New_Delhi.jpg/330px-Painted_prayers%2C_Warli_paintings%2C_at_Sanskriti_Kendra%2C_Anandagram%2C_New_Delhi.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail','2026-08-17 12:55:19'),(124,'Aranmula Kannadi','Handicraft','Kerala','Pathanamthitta','Handcrafted metal mirrors made from a secret bronze alloy, produced by only a few families in Aranmula village.','Discover the enchanting beauty of the Aranmula Kannadi, a unique metal mirror handcrafted in the village of Aranmula in Pathanamthitta, Kerala. Cast from a secret bronze alloy, these extraordinary mirrors are produced by only a few local families who keep this traditional art alive. Bring home a piece of this rare heritage and experience a beautiful reflection born of pure craftsmanship.',9.330600,76.825600,'https://upload.wikimedia.org/wikipedia/commons/thumb/5/55/Aranmula_mirror_high_quality_bronze_mirror.jpg/330px-Aranmula_mirror_high_quality_bronze_mirror.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail','2026-08-17 12:55:19'),(125,'Nagaland Bamboo Craft','Handicraft','Nagaland','Dimapur','Traditional bamboo and cane products including baskets, mats, and furniture, integral to Naga tribal daily life and festivals.','Step into the rich heritage of Dimapur and discover the beautiful bamboo and cane crafts that form the heartbeat of Nagaland. From intricately woven baskets and mats to traditional furniture, these creations are central to both daily tribal life and festive celebrations. Experience this enduring art form first-hand and connect with a beautiful, living tradition of the Naga people.',25.909100,93.726700,'https://upload.wikimedia.org/wikipedia/commons/thumb/c/cb/Kapamodzu.jpg/330px-Kapamodzu.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail','2026-08-17 12:55:19'),(126,'Kani Shawl','Textile','Jammu and Kashmir','Srinagar','Intricately woven shawls using small wooden \'kani\' sticks instead of a shuttle, taking months to complete one piece.','Discover the breathtaking textile artistry of Srinagar, Jammu and Kashmir, through the legendary Kani Shawl. Each masterpiece is intricately woven using small wooden \'kani\' sticks instead of a traditional shuttle, a meticulous process that takes dedicated artisans months to complete just a single piece. Wrap yourself in a timeless story of patience and skill on your journey through this beautiful region.',34.083700,74.797300,'https://upload.wikimedia.org/wikipedia/commons/5/5f/%DA%A9%D8%B4%D9%85%DB%8C%D8%B1_%D8%B3%DB%92_%DB%81%D8%A7%D8%AA%DA%BE_%D8%B3%DB%92_%D8%A8%D9%86%DB%8C_%DA%A9%D8%A7%D9%86%DB%8C_%D8%B4%D8%A7%D9%84.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(127,'Walnut Wood Carving','Handicraft','Jammu and Kashmir','Srinagar','Ornately carved furniture and decor made from Kashmir walnut wood, renowned for its fine grain and durability.','Discover the breathtaking artistry of Srinagar through its legendary walnut wood carving. Renowned for its fine grain and remarkable durability, this Kashmir specialty is transformed into ornately carved furniture and beautiful decor. Bring home a piece of this exquisite heritage and let the warmth of Jammu and Kashmir elevate your space.',34.083700,74.797300,'https://upload.wikimedia.org/wikipedia/commons/4/42/Walnut_wood_carving.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(128,'Banaras Brocade','Textile','Uttar Pradesh','Varanasi','Rich zari-woven brocade fabric used in sarees and garments, a Varanasi weaving specialty distinct from plain silk.','Step into the vibrant world of Varanasi and discover the breathtaking beauty of Banaras Brocade. Distinct from plain silk, this exquisite local specialty features rich, intricate zari weaving that transforms sarees and garments into shimmering works of art. Let the warmth of Uttar Pradesh\'s weaving traditions wrap around you as you explore this timeless textile masterpiece.',25.317600,82.973900,'https://upload.wikimedia.org/wikipedia/commons/4/4e/%27Sari%27_from_Varanasi_%28north-central_India%29%2C_silk_and_gold-wrapped_silk_yarn_with_supplementary_weft_brocade.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(129,'Lucknow Zardozi','Textile','Uttar Pradesh','Lucknow','Heavy metallic thread embroidery using gold and silver wire, historically adorning royal garments.','Discover the royal elegance of Lucknow Zardozi, a magnificent textile craft hailing from the historic city of Lucknow in Uttar Pradesh. This exquisite art form features heavy metallic thread embroidery crafted with gold and silver wire, which historically adorned the lavish garments of royalty. Let yourself be captivated by the shimmering beauty of this timeless craft as you explore the region\'s vibrant heritage.',26.846700,80.946200,'https://upload.wikimedia.org/wikipedia/commons/3/35/Close_Shot_of_the_Zardozi_%28Zardouzi%29_Embroidery_Cushion_Covers.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(130,'Firozabad Glassware','Handicraft','Uttar Pradesh','Firozabad','Hand-blown coloured glass bangles and decorative items, earning Firozabad the title \'Glass City of India\'.','Welcome to Firozabad, Uttar Pradesh, affectionately known as the \"Glass City of India\" for its incredible traditional handicraft. Discover a dazzling world of vibrant colors as you explore hand-blown glass bangles and exquisite decorative items crafted by local artisans. It is a mesmerizing heritage of artistry waiting to light up your travels.',27.159200,78.395700,'https://upload.wikimedia.org/wikipedia/commons/9/93/Firozabad_UP_2.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(131,'Meerut Scissors','Handicraft','Uttar Pradesh','Meerut','Traditional hand-forged scissors and cutting tools, a centuries-old metalworking craft of Meerut.','Discover the legendary Meerut Scissors, a centuries-old metalworking tradition from the heart of Uttar Pradesh. Each pair of these unique cutting tools is meticulously hand-forged by local artisans, keeping a timeless handicraft alive. Take home a piece of Meerut\'s heritage with a beautiful, enduring tool that represents generations of master craftsmanship.',28.984500,77.706400,'https://upload.wikimedia.org/wikipedia/commons/1/18/Mustafa_Castle_--_night_shot.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(132,'Sanganeri Hand Block Print','Textile','Rajasthan','Jaipur','Fine hand block printing tradition distinct from Bagru, known for delicate floral motifs on light backgrounds.','Discover the elegant artistry of Sanganeri Hand Block Printing, a beloved textile tradition from Jaipur, Rajasthan. Uniquely distinct from nearby Bagru, this exquisite craft is known for its delicate floral motifs stamped gracefully onto light backgrounds. Bring home a piece of this timeless heritage and let its gentle beauty brighten your journey.',26.985500,75.851300,'https://upload.wikimedia.org/wikipedia/en/b/bd/Woodblock_Printing_Craft_of_Bagh%2C_Madhya_Pradesh%2C_India.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(133,'Kota Doria','Textile','Rajasthan','Kota','Lightweight, sheer cotton-silk fabric woven in a distinctive checkered pattern called khat.','Discover the airy elegance of Kota Doria, a celebrated textile masterpiece crafted in the historic region of Kota, Rajasthan. This exquisite, sheer fabric beautifully blends cotton and silk, distinguished by its signature checkered pattern known as khat. Lightweight and inviting, it is the perfect artistic souvenir to remember your journey through Rajasthan.',25.213800,75.864800,'https://upload.wikimedia.org/wikipedia/commons/8/84/Genuine_handloom_kota_doria_masterpiece.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(134,'Molela Clay Work','Handicraft','Rajasthan','Rajsamand','Terracotta plaques depicting deities and folk gods, handmade by the Kumhar potter community of Molela village.','Discover the fascinating world of Molela Clay Work, a beautiful terracotta craft from Rajsamand, Rajasthan. Handcrafted by the skilled Kumhar potter community of Molela village, these unique plaques beautifully depict traditional deities and folk gods. Bring home a piece of this rich heritage and let these warm, handmade creations connect you to the artistic soul of the region.',25.070800,73.881900,'https://gaatha.com/wp-content/uploads/2009/11/MOLELA-TERRACOTTA-PLAQUE.jpg','2026-08-17 12:55:19'),(135,'Meenakari Jewelry','Handicraft','Rajasthan','Jaipur','Vivid enamel work on gold and silver jewelry, a Mughal-era craft perfected by Jaipur\'s artisans.','Discover the breathtaking beauty of Meenakari, a Mughal-era craft perfected by the master artisans of Jaipur. This exquisite art adorns gold and silver jewelry with vivid, colorful enamel work to create truly captivating treasures. It is the perfect way to carry a piece of Rajasthan\'s brilliant artistic heritage with you.',26.912400,75.787300,'https://upload.wikimedia.org/wikipedia/commons/3/38/Meenakaari_art_from_Iran.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(136,'Pipli Applique Work','Handicraft','Odisha','Puri','Colourful applique craft using cutout fabric patches, traditionally used for temple umbrellas and canopies.','Discover the vibrant world of Pipli Applique Work, a captivating handicraft from the heart of Puri, Odisha. This beautiful art form uses colourful cutout fabric patches to create stunning designs, traditionally crafted to adorn majestic temple umbrellas and grand canopies. Let these bright, festive creations capture your imagination and add a touch of IndiaΓÇÖs rich heritage to your journey.',20.106400,85.818900,'https://upload.wikimedia.org/wikipedia/commons/1/12/Pipli_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original','2026-08-17 12:55:19'),(137,'Konark Stone Carving','Handicraft','Odisha','Puri','Intricate stone sculpture tradition famous for the carvings of the Konark Sun Temple.','Step into the world of Konark Stone Carving, a magnificent handicraft tradition from Puri, Odisha, that turns stone into breathtaking art. Famous for the intricate stone sculptures that reflect the grandeur of the iconic Konark Sun Temple, this craft is a true marvel of detail and dedication. Explore these stunning creations and witness a legendary heritage carved in stone.',19.887600,86.094500,'https://upload.wikimedia.org/wikipedia/commons/e/ee/Stone_work_at_Konark_Orissa_India.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(138,'Cuttack Silver Filigree','Handicraft','Odisha','Cuttack','Delicate silver wire jewelry and decor, hand-twisted into intricate lace-like patterns by Cuttack\'s silversmiths.','Step into the shining heritage of Cuttack, Odisha, and discover the mesmerizing art of Silver Filigree. Here, talented local silversmiths hand-twist delicate silver wire into incredibly intricate, lace-like jewelry and decor. It is a truly breathtaking handicraft that makes for the perfect, elegant keepsake of your travels.',20.462500,85.882800,'https://upload.wikimedia.org/wikipedia/commons/7/75/Portuguese_filigree_intricate_work.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(139,'Baluchari Saree','Textile','West Bengal','Murshidabad','Silk sarees woven with elaborate mythological and courtly scenes on the pallu, originating in the Murshidabad region.','Step into the rich heritage of West Bengal with the exquisite Baluchari Saree, a textile masterpiece originating from the Murabad region. Woven from fine silk, these beautiful garments tell captivating stories through the elaborate mythological and courtly scenes detailed on their pallus. Bring home a piece of wearable art that beautifully captures the soul of traditional Indian craftsmanship.',24.183300,88.266700,'https://upload.wikimedia.org/wikipedia/commons/a/a8/Baluchari_saree_of_Bishnupur_DSC06029.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(140,'Dhaniakhali Saree','Textile','West Bengal','Hooghly','Fine cotton sarees with a distinctive red border, woven in the Dhaniakhali region of Hooghly district.','Discover the timeless charm of West BengalΓÇÖs textile heritage with the elegant Dhaniakhali Saree, beautifully crafted in the Hooghly district. Woven from fine cotton, these traditional sarees are instantly recognizable by their distinctive and striking red borders. Bring home a piece of the Dhaniakhali region\'s artistry with this beautiful, wearable keepsake from your travels.',22.999700,88.106700,'https://upload.wikimedia.org/wikipedia/commons/3/3e/Dhaniakhali_in_Hooghly_%28West_Bengal%29.svg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(141,'Nakshi Kantha','Textile','West Bengal','Birbhum','Hand-embroidered quilts and textiles using running stitch to create intricate folk motifs, a Bengal tradition passed through generations.','Discover the warmth of a timeless Bengal tradition with Nakshi Kantha, a beautiful hand-embroidery craft from Birbhum, West Bengal. Passed down through generations, these unique quilts and textiles feature intricate folk motifs meticulously created using a simple running stitch. It is a piece of living heritage you will love uncovering on your journey.',23.810300,87.528900,'https://upload.wikimedia.org/wikipedia/commons/2/29/Nakshi_kantha1.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(142,'Purulia Chau Mask','Handicraft','West Bengal','Purulia','Vividly painted papier-mache masks worn during the traditional Chau dance-drama of Purulia.','Discover the vibrant artistry of West Bengal through the mesmerizing Purulia Chau Mask. Handcrafted from papier-mache and vividly painted, these striking masks are traditionally worn during the regionΓÇÖs captivating Chau dance-drama. Explore this unique handicraft and let its dramatic beauty connect you to the rich living heritage of Purulia.',23.332000,86.361600,'https://upload.wikimedia.org/wikipedia/commons/2/2d/Chhau_Mask_of_Charida.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(143,'Santiniketan Leather Goods','Handicraft','West Bengal','Birbhum','Hand-tooled and batik-dyed leather bags and accessories originating from the Santiniketan region founded by Tagore.','Step into the artistic heritage of Birbhum, West Bengal, and discover the beautiful charm of Santiniketan leather goods. Originating from the historic region founded by Tagore, these exquisite bags and accessories are meticulously hand-tooled and brought to life with vibrant batik dyes. Take home a piece of this unique craftsmanship, where tradition and timeless style meet in every hand-crafted detail.',23.682100,87.683200,'https://upload.wikimedia.org/wikipedia/commons/6/6c/Santiniketan_4426.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(144,'Muga Silk','Textile','Assam','Sivasagar','The world\'s only golden-hued silk, produced from silkworms native to Assam, prized for its natural sheen and durability.','Discover the golden treasure of Sivasagar, Assam, with the breathtaking Muga Silk, the world\'s only naturally golden-hued textile. Spun from silkworms native to this region, this exquisite fabric is highly prized for its brilliant natural sheen and remarkable durability. It is the perfect, shimmering keepsake to connect you with the rich heritage of Assam.',26.985200,94.637300,'https://upload.wikimedia.org/wikipedia/commons/c/c0/Assamese_Muga_With_Japi.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(145,'Sarthebari Bell Metal Craft','Metalwork','Assam','Barpeta','Traditional bell metal utensils and ritual items hand-hammered by artisans of Sarthebari village.','Step into the rich heritage of Barpeta, Assam, and discover the shining beauty of Sarthebari Bell Metal Craft. Meticulously hand-hammered by skilled village artisans, these traditional utensils and ritual items represent a timeless metalwork legacy. Bring home one of these unique creations to forever cherish a piece of Assam\'s living artistry.',26.452300,91.005900,'https://upload.wikimedia.org/wikipedia/commons/b/b4/%E0%A6%AC%E0%A6%BE%E0%A6%A3%E0%A6%AC%E0%A6%BE%E0%A6%A4%E0%A6%BF.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(146,'Naga Shawl Weaving','Textile','Nagaland','Kohima','Distinctively patterned tribal shawls woven by Naga communities, with designs signifying clan and social status.','Step into the heart of Kohima, Nagaland, and discover the breathtaking beauty of Naga Shawl Weaving. These distinctively patterned tribal shawls are far more than just beautiful textiles; their intricate designs serve as a visual language signifying the wearerΓÇÖs clan and social status. We invite you to explore this warm, living tradition and experience the rich heritage of the Naga communities.',25.675100,94.108600,'https://upload.wikimedia.org/wikipedia/commons/7/7c/Ao_Naga_lady_in_her_traditional_attire.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(147,'Moirang Phee','Textile','Manipur','Bishnupur','Handwoven textile with distinctive temple-border motifs, traditionally worn by Manipuri women.','Discover the elegant artistry of Manipur with Moirang Phee, a stunning handwoven textile hailing from the historic region of Bishnupur. Traditionally worn by Manipuri women, this beautiful fabric is defined by its distinctive and unique temple-border motifs. It is a truly captivating piece of local heritage waiting for you to explore.',24.631700,93.778300,'https://upload.wikimedia.org/wikipedia/commons/c/c7/Wangkhei_Phee.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(148,'Toda Embroidery','Textile','Tamil Nadu','Nilgiris','Distinctive red-and-black embroidery on white cotton shawls, practiced by the Toda tribal community of the Nilgiris.','Discover the striking beauty of Toda Embroidery, a unique textile art practiced by the Toda tribal community in the Nilgiris of Tamil Nadu. This distinctive craft features bold red-and-black embroidery on elegant white cotton shawls. It is a beautiful piece of local heritage waiting to be discovered on your journey.',11.406400,76.693200,'https://upload.wikimedia.org/wikipedia/commons/b/b3/Toda_man_wearing_a_hawl_made_of_Toda_embroidery.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(149,'Mahabalipuram Stone Sculpture','Handicraft','Tamil Nadu','Chengalpattu','Granite stone sculpture tradition dating to the Pallava dynasty, famous for the rock-cut monuments of Mahabalipuram.','Step into the timeless world of Mahabalipuram Stone Sculpture, a magnificent granite craft from Chengalpattu, Tamil Nadu. Originating during the historic Pallava dynasty, this tradition is famous for creating the spectacular rock-cut monuments that define the region. Take a piece of this ancient artistry home with you and let the enduring spirit of Tamil Nadu inspire your journey.',12.620800,80.198200,'https://upload.wikimedia.org/wikipedia/commons/f/f2/Mamallapuram_view.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(150,'Thanjavur Bommai','Handicraft','Tamil Nadu','Thanjavur','Traditional bobble-head dolls hand-painted in vivid colours, a folk craft distinct from Thanjavur paintings.','Discover the delightful charm of the Thanjavur Bommai, a traditional folk craft native to Thanjavur, Tamil Nadu. Distinct from the region\'s famous paintings, these whimsical bobble-head dolls are lovingly hand-painted in vivid colours. They make a wonderfully cheerful keepsake to bring home from your travels.',10.787000,79.137800,'https://upload.wikimedia.org/wikipedia/commons/8/81/Thanjavur_2.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(151,'Bhavani Jamakkalam','Textile','Tamil Nadu','Erode','Thick handwoven cotton floor rugs with characteristic mixed-colour warp threads, woven in Bhavani town.','Discover the rich heritage of Erode, Tamil Nadu, through the beautiful art of Bhavani Jamakkalam. Woven in the town of Bhavani, these thick, handwoven cotton floor rugs are instantly recognizable by their unique mixed-colour warp threads. Bring home one of these authentic textile treasures to add a touch of traditional Indian warmth to your favorite space.',11.446300,77.683900,'https://upload.wikimedia.org/wikipedia/commons/3/3a/Jamakalam.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(152,'Salem Silk','Textile','Tamil Nadu','Salem','Pure mulberry silk textiles woven in Salem, known for their fine texture and vibrant natural dyes.','Discover the elegance of Salem Silk, a cherished textile tradition from the historic region of Salem in Tamil Nadu. Woven from pure mulberry silk, these exquisite fabrics are celebrated for their remarkably fine texture and the brilliant natural dyes that bring them to life. Take home a piece of this beautiful craft to experience a true masterpiece of Indian weaving.',11.664300,78.146000,'https://upload.wikimedia.org/wikipedia/commons/8/8d/Silk_Handloom_Salem_TN_-_2.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(153,'Kolhapuri Chappal','Handicraft','Maharashtra','Kolhapur','Handcrafted leather sandals made using vegetable-tanned leather, worn for centuries and famous worldwide.','Discover the world-famous Kolhapuri Chappal, a legendary handcrafted sandal from the vibrant region of Kolhapur, Maharashtra. Worn for centuries, these iconic sandals are meticulously created using traditional vegetable-tanned leather. Take home a beautiful piece of this rich Indian handicraft and step into a timeless heritage.',16.705000,74.243300,'https://upload.wikimedia.org/wikipedia/commons/8/8a/Indian_chappal%2C_Kolhapur%2C_late_20th_century_-_Bata_Shoe_Museum_-_DSC00445.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(154,'Paithani Saree','Textile','Maharashtra','Aurangabad','Richly woven silk sarees with peacock and floral motifs and a distinctive oblique square border.','Discover the exquisite artistry of Maharashtra with the Paithani Saree, a treasured textile tradition from Aurangabad. These richly woven silk sarees are adorned with elegant peacock and floral motifs, beautifully framed by a highly distinctive oblique square border. Let the timeless elegance of this stunning masterpiece captivate you as you explore the region\'s rich heritage.',19.876200,75.343300,'https://upload.wikimedia.org/wikipedia/commons/0/03/Paithani_Bridal_Sari_LACMA_M.75.4.23_%282_of_2%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(155,'Himroo Shawl','Textile','Maharashtra','Aurangabad','Woven fabric blending cotton, silk, and zari, historically developed as an affordable alternative to Kinkhwab brocade.','Discover the exquisite charm of the Himroo shawl, a legendary textile treasure waiting for you in Aurangabad, Maharashtra. Beautifully woven from a blend of cotton, silk, and shimmering zari, this craft was historically created as an affordable yet luxurious alternative to royal Kinkhwab brocade. Wrap yourself in its timeless elegance and take a true piece of Indian heritage home with you.',19.876200,75.343300,'https://upload.wikimedia.org/wikipedia/commons/0/0a/Himroo.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(156,'Bhagalpuri Tussar Silk','Textile','Bihar','Bhagalpur','Wild tussar silk textiles, earning Bhagalpur the nickname \'Silk City of Bihar\'.','Step into the vibrant world of Bhagalpuri Tussar Silk, the legendary textile that has earned Bhagalpur the proud nickname of the \'Silk City of Bihar\'. This exquisite, wild tussar silk is a true masterpiece of traditional craftsmanship, offering a beautiful connection to the region\'s rich heritage. Discover the magic woven into every thread and bring home a timeless piece of Bihar.',25.242500,87.007900,'https://upload.wikimedia.org/wikipedia/commons/2/26/Stamp_of_India_-_2018_-_Colnect_802136_-_Traditional_Handloom_Textiles_-_Bhagalpur_Silk.jpeg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(157,'Sujini Embroidery','Textile','Bihar','Muzaffarpur','Hand-stitched quilted embroidery depicting rural life and folklore, traditionally made by women of Bihar.','Discover the heartwarming beauty of Sujini embroidery, a unique quilted textile tradition lovingly hand-stitched by the women of Muzaffarpur, Bihar. Every intricate thread tells a story, beautifully depicting vibrant scenes of rural life and local folklore. It is an enchanting craft that invites you to hold a piece of Bihar\'s rich storytelling heritage right in your hands.',26.122500,85.390600,'https://www.gaonconnection.com/wp-content/uploads/2024/05/357470-bihar-sujani-embroidery-women-empowerment-unesco-gi-tag-handicrafts-mithila-madhubani-livelihood-3.webp','2026-08-17 12:55:19'),(158,'Sikki Grass Craft','Handicraft','Bihar','Madhubani','Fine golden grass woven into decorative boxes, toys and idols, a traditional Mithila handicraft.','Discover the warm glow of Sikki Grass Craft, a traditional Mithila handicraft from Madhubani, Bihar. This beautiful art transforms fine golden grass into hand-woven decorative boxes, playful toys, and elegant idols. Bringing home one of these unique creations is the perfect way to cherish your journey and keep the spirit of this rich heritage with you.',26.357300,86.072500,'https://upload.wikimedia.org/wikipedia/en/8/8f/Sikki_grass_craft.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(159,'Chanderi Saree','Textile','Madhya Pradesh','Ashoknagar','Sheer, lightweight sarees woven with gold and silver zari, blending silk and cotton threads.','Discover the ethereal beauty of the Chanderi saree, a prized textile tradition from Ashoknagar, Madhya Pradesh. This masterpiece seamlessly blends silk and cotton threads into a sheer, lightweight fabric adorned with shimmering gold and silver zari. Feel the touch of this exquisite craft and take home a truly elegant piece of Indian heritage.',24.722200,78.137800,'https://upload.wikimedia.org/wikipedia/commons/1/12/Chanderi_Silk_Sari_outside_a_village_home_in_Pranpur._%287045778685%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(160,'Maheshwari Saree','Textile','Madhya Pradesh','Khargone','Distinctive reversible-border sarees woven in Maheshwar, patronised by Holkar queen Ahilyabai.','Discover the elegant Maheshwari saree, a royal textile tradition woven in the historic town of Maheshwar in Khargone, Madhya Pradesh. Patronised by the Holkar queen Ahilyabai, these beautiful creations are famous for their distinctive reversible borders. Take home a piece of this rich heritage as a special keepsake from your travels.',22.179900,75.585900,'https://upload.wikimedia.org/wikipedia/commons/7/73/Hina_Khan_walk_the_ramp_at_Lakme_Fashion_Week_2023_%28cropped%29_2.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(161,'Gond Painting','Art','Madhya Pradesh','Dindori','Vivid dot-and-line folk art created by the Gond tribal community depicting nature and mythology.','Step into a world of vibrant storytelling with Gond Painting, a captivating folk art nurtured by the Gond tribal community of Dindori, Madhya Pradesh. Each masterpiece uses a mesmerizing language of vivid dots and lines to breathe life into sacred tales of nature and mythology. Let these soulful creations connect you to the very heart of the region\'s rich artistic heritage.',22.942500,81.078800,'https://upload.wikimedia.org/wikipedia/commons/c/cf/Women_in_adivasi_village%2C_Umaria_district%2C_India.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(162,'Bastar Wood Carving','Handicraft','Chhattisgarh','Bastar','Intricately carved wooden sculptures and masks made by tribal artisans of Bastar, depicting deities and folklore.','Discover the vibrant spirit of Chhattisgarh through the beautiful art of Bastar Wood Carving. Handcrafted by local tribal artisans, these intricately carved wooden sculptures and masks bring ancient deities and rich folklore to life. Bring home a unique piece of this timeless handicraft to cherish the stories of Bastar forever.',19.107300,81.954200,'https://production.ruralindiaonline.org/uploads/09_H0_M_0125_PKK_Carving_a_life_out_of_wood_in_Bastar_a89097626f.jpg','2026-08-17 12:55:19'),(163,'Kashmiri Hand-Knotted Carpet','Textile','Jammu and Kashmir','Srinagar','Hand-knotted silk and wool carpets with intricate Persian-influenced patterns, woven knot-by-knot on traditional looms.','Discover the breathtaking artistry of Srinagar through the legendary Kashmiri hand-knotted carpet. Each masterpiece is meticulously woven knot-by-knot on traditional looms, blending fine silk and wool into intricate, Persian-influenced patterns. Bringing one of these luxurious textiles home means carrying a piece of Jammu and Kashmir\'s heritage with you.',34.083700,74.797300,'https://upload.wikimedia.org/wikipedia/commons/7/74/Kmrwalnut.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19'),(164,'Sujani Craft of Bihar','Textile','Bihar','Bhagalpur','Layered cotton quilts hand-stitched with running stitch to depict social and rural themes, a Bihar craft tradition.','Discover the warmth of BiharΓÇÖs heritage through Sujani, a captivating textile tradition from Bhagalpur. Using a simple running stitch, artisans carefully layer soft cotton quilts to hand-stitch vivid scenes depicting social and rural themes. It is a heartwarming craft where every thread tells a story of local life, making it a truly unique piece of art to take home.',25.242500,87.007900,'https://upload.wikimedia.org/wikipedia/commons/7/74/Stamp_of_India_-_2019_-_Colnect_924655_-_Sujani_Embroidery.jpeg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original','2026-08-17 12:55:19'),(165,'Dokra Metal Craft of Bengal','Metalwork','West Bengal','Bankura','Ancient lost-wax metal casting technique producing bronze figurines, practiced by tribal artisans of West Bengal.','Welcome to the world of Dokra, an ancient metal craft lovingly preserved by the tribal artisans of Bankura, West Bengal. Through a fascinating lost-wax casting technique, these skilled makers transform bronze into stunning, one-of-a-kind figurines. Explore this captivating craft and discover a timeless piece of Bengal\'s rich artistic heritage.',23.232400,87.073900,'https://upload.wikimedia.org/wikipedia/commons/3/35/Village_lady_grinding_ants_for_her_family.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=original','2026-08-17 12:55:19');
